window.RP_SESSION={"id":"S-e7a51829d929","messages":[{"id":"RP-II-0179638","time":"2026-09-04T13:27:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"정말인가, 집에 돌아왔어!\n\n—한동안 의뢰는 쉬어야겠다. 어디보자...","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179639","time":"2026-09-04T13:28:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"오드리님은 지금 뭐하지? 회포를 풀고 싶은데.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179640","time":"2026-09-04T13:28:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"아치타님께 해적검도 받아야하고.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179641","time":"2026-09-04T13:28:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"데이지는 잘 있나? 아코니님은 어디 있으려나?","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179642","time":"2026-09-04T13:29:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"얀님은 아직도 감자를 먹고 있나? 아, 그러고보니 그 주정뱅이 마법사 목걸이도 아직 나한테 있네.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179643","time":"2026-09-04T13:30:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"토르번님은 여전히 바쁜가? 머독님은 뭐하시지?","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179644","time":"2026-09-04T13:30:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"아마이조님이나 허그님은 당분간 마주치고 싶지 않네. 체력 회복이 필요해... 분명 마주치면 훈련장이나 술집에 끌려갈꺼야...","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179645","time":"2026-09-04T13:31:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"유령화에 대한 것도 생각해야겠네. 어쩐지 묘하게 쓰는 방식이 바뀌었는데.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179646","time":"2026-09-04T13:32:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이제 갑옷을 입은 기사나 외피가 단단한 거대 곤충은 어떻게 상대하지? 션님께 물어볼까...","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179647","time":"2026-09-04T13:33:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"아키라님도 나쁘지 않은 선택일지도 모르겠는데. 근데... 요령을 듣기보단 이해하기 어려운 훈련을 받게 될 것 같아. 역시 이쪽은 관두자.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179648","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"레네르트님이나 벨마이어님은 이제 뭐하시지? 얼굴 좀 비치시나?","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179649","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"브랜님은 지금도 대장간에 있으려나?","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179650","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"... ...","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179651","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"다음 할 일은 일단 자고 생각할까.","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179652","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-4a533e2105f8"]},{"id":"RP-II-0179653","time":"2026-09-04T13:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
